function highlightSocialMediaHandlesAndUrls(text, color) {
  // Extended regular expression to match hashtags, mentions, and URLs
  const handleAndUrlRegex = /([#@]\S+|\bhttps?:\/\/\S+\.\S+\b)/g;

  return text.replace(handleAndUrlRegex, (match) => {
    // Check if the match is a URL
    if (/^https?:\/\//.test(match)) {
      // Return as hyperlink
      return `<a href="${match}" style="color: ${color};">${match}</a>`;
    } else {
      // Return as span for hashtags and mentions
      return `<span style="color: ${color};">${match}</span>`;
    }
  });
}

